"use client"

import { useState } from "react";
import z from "zod"
import Modal from "../../components/ui/Modal/Modal";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useCreateServiceCategory, useDeleteServiceCategory, useGetServiceCategory, usePutServiceCategory } from "@/src/lib/ReactQuery/query/admin/service-categories/query";
import { useRouter } from "next/navigation";
import { TServiceCategory } from "@/src/types";

const serviceCategorySchema = z.object({
    title: z.string(),
    sortOrder: z.string(),
    isActive: z.string(),
})
type TserviceCategorySchema = z.infer<typeof serviceCategorySchema>;

const serviceCategoryPutSchema = z.object({
    id: z.string(),
    title: z.string(),
    sortOrder: z.string(),
    isActive: z.string(),
})
type TserviceCategoryPutSchema = z.infer<typeof serviceCategoryPutSchema>;

export default function ServiceCategoriesPage() {
    const router = useRouter();
    const [isOpenCreate, setIsOpenCreate] = useState<boolean>(false);
    //сделать форму обновления категории услуг
    const [isOpenPut, setIsOpenPut] = useState<boolean>(false);
    const createServiceCategory = useCreateServiceCategory();
    const deleteServiceCategory = useDeleteServiceCategory();
    const putServiceCategory = usePutServiceCategory();
    const serviceCategory = useGetServiceCategory();
    const { register, handleSubmit, formState: { errors }, reset } = useForm<TserviceCategorySchema>({
        resolver: zodResolver(serviceCategorySchema),
        defaultValues: {
            title: "",
            sortOrder: "0",
            isActive: "true"
        }
    })
    async function onSubmit(data: TserviceCategorySchema) {
        createServiceCategory.mutate(data, {
            onSuccess: () => {
                reset();
                setIsOpenCreate(false);
            }
        })
    }

    const { register: registerPut, handleSubmit: handleSubmitPut, formState: { errors: errorsPut }, reset: resetPut } = useForm<TserviceCategoryPutSchema>({
        resolver: zodResolver(serviceCategoryPutSchema),
        defaultValues: {
            id: "",
            title: "",
            sortOrder: "0",
            isActive: "true"
        }
    })

    function handleEditClick(service: TServiceCategory) {
        resetPut({
            id: service.id,
            title: service.title,
            sortOrder: String(service.sortOrder),
            isActive: String(service.isActive)
        });
        setIsOpenPut(true);
    }

    async function onSubmitPut(data: TserviceCategoryPutSchema) {
        putServiceCategory.mutate(data, {
            onSuccess: () => {
                resetPut();
                setIsOpenPut(false);
            }
        })
    }
    return<main>
        <h1>Управление категориями услуг</h1>
        <section>
            <button onClick={() => setIsOpenCreate(true)}>Создать</button>
            {serviceCategory.isLoading && <p>Загрузка категорий...</p>}
            
            <table>
                <thead>
                    <tr>
                        <th>ID</th>
                        <th>Название</th>
                        <th>Сортировка</th>
                        <th>Статус</th>
                    </tr>
                </thead>
                <tbody>
                    {serviceCategory.data?.map((service : TServiceCategory) => {

                        return(<tr key={service.id}>
                            <td>{service.id.slice(0,12)}...</td>
                            <td>{service.title}</td>
                            <td>{service.sortOrder}</td>
                            <td>
                                <span>{service.isActive ? "Активно" : "Неактивна"}</span>
                            </td>
                            <td>
                                <button onClick={() => handleEditClick(service)}>✏️</button>
                                <button onClick={() => {
                                    const conf = confirm("Вы уверены?");
                                    if(conf) deleteServiceCategory.mutate({ id: service.id })
                                }}>🗑️</button>
                            </td>
                        </tr>)
                    })}
                </tbody>
            </table>

        </section>
        <Modal isOpen={isOpenCreate} onClose={() => setIsOpenCreate(false)}>
            <h3>Новая категория</h3>
            <form onSubmit={handleSubmit(onSubmit)}>
                <label htmlFor="title">Название: </label>
                <input type="text" {...register("title")} maxLength={30} />
                <label htmlFor="sortOrder">Сортировка: </label>
                <input type="number" {...register("sortOrder")} />
                <label htmlFor="isActive">Активный: </label>
                <select {...register("isActive")}>
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                </select>
                <button type="submit">Создать</button>
            </form>
            <button onClick={()=> setIsOpenCreate(false)}>Закрыть</button>
        </Modal>
        <Modal isOpen={isOpenPut} onClose={() => setIsOpenPut(false)}>
            <h3>Изменить категорию</h3>
            <form onSubmit={handleSubmitPut(onSubmitPut)}>
                <input type="hidden" {...registerPut("id")} />
                <label htmlFor="title">Название: </label>
                <input type="text" {...registerPut("title")} maxLength={30} />
                <label htmlFor="sortOrder">Сортировка: </label>
                <input type="number" {...registerPut("sortOrder")} />
                <label htmlFor="isActive">Активный: </label>
                <select {...registerPut("isActive")}>
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                </select>
                <button type="submit">Изменить</button>
            </form>
            <button onClick={()=> setIsOpenPut(false)}>Закрыть</button>
        </Modal>
    </main>
}